/* Offline JsBarcode Compatible Engine (Code128B SVG & Canvas) */
(function(global){
  const PATTERNS = [
    "11011001100","11001101100","11001100110","10010011000","10010001100","10001001100",
    "10011001000","10011000100","10001100100","11001001000","11001000100","11000100100",
    "10110011100","10011011100","10011001110","10111001100","10011101100","10011100110",
    "11001110010","11001011100","11001001110","11011100100","11001110100","11101101110",
    "11101001100","11100101100","11100100110","11101100100","11100110100","11100110010",
    "11011011000","11011000110","11000110110","10100011000","10001011000","10001000110",
    "10110001000","10001101000","10001100010","11010001000","11000101000","11000100010",
    "10110111000","10110001110","10001101110","10111011000","10111000110","10001110110",
    "11101110110","11010001110","11000101110","11011101000","11011100010","11011101110",
    "11101011000","11101000110","11100010110","11101101000","11101100010","11100011010",
    "11101111010","11001000010","11110001010","10100110000","10100001100","10010110000",
    "10010000110","10000101100","10000100110","10110010000","10110000100","10011010000",
    "10011000010","10000110100","10000110010","11000010010","11001010000","11110111010",
    "11000010100","10001111010","10100111100","10010111100","10010011110","10111100100",
    "10011110100","10011110010","11110100100","11110010100","11110010010","11011011110",
    "11011110110","11110110110","10101111000","10100011110","10001011110","10111101000",
    "10111100010","11110101000","11110100010","10111011110","10111101110","11101011110",
    "11110101110","11010000100","11010010000","11010011100","1100011101011"
  ];
  function encode128B(raw){
    const text = String(raw || '000000').replace(/[^\x20-\x7E]/g, '') || '000000';
    const codes = [104];
    let sum = 104;
    for(let i=0;i<text.length;i++){
      const v = text.charCodeAt(i) - 32;
      const safe = (v >= 0 && v <= 95) ? v : 16;
      codes.push(safe);
      sum += safe * (i + 1);
    }
    codes.push(sum % 103);
    codes.push(106);
    return { text, bits: codes.map(c => PATTERNS[c] || PATTERNS[0]).join('') };
  }
  function JsBarcode(target, value, opts){
    opts = Object.assign({ width: 2, height: 50, displayValue: true, fontSize: 13, margin: 8, background: '#ffffff', lineColor: '#000000' }, opts || {});
    const el = typeof target === 'string' ? document.querySelector(target) : target;
    if(!el) return;
    const { text, bits } = encode128B(value);
    const w = (bits.length * opts.width) + (opts.margin * 2);
    const textH = opts.displayValue ? (opts.fontSize + 6) : 0;
    const h = opts.height + (opts.margin * 2) + textH;
    if(el.tagName && el.tagName.toLowerCase() === 'svg'){
      el.setAttribute('viewBox', `0 0 ${w} ${h}`);
      el.setAttribute('width', w);
      el.setAttribute('height', h);
      let inner = `<rect x="0" y="0" width="${w}" height="${h}" fill="${opts.background}"/>`;
      let x = opts.margin;
      for(let i=0;i<bits.length;i++){
        if(bits[i]==='1') inner += `<rect x="${x}" y="${opts.margin}" width="${opts.width}" height="${opts.height}" fill="${opts.lineColor}"/>`;
        x += opts.width;
      }
      if(opts.displayValue){
        inner += `<text x="${w/2}" y="${opts.margin + opts.height + opts.fontSize + 2}" text-anchor="middle" font-family="monospace" font-size="${opts.fontSize}" font-weight="bold" fill="${opts.lineColor}">${text}</text>`;
      }
      el.innerHTML = inner;
    } else if(el.getContext){
      el.width = w; el.height = h;
      const ctx = el.getContext('2d');
      ctx.fillStyle = opts.background; ctx.fillRect(0,0,w,h);
      ctx.fillStyle = opts.lineColor;
      let x = opts.margin;
      for(let i=0;i<bits.length;i++){
        if(bits[i]==='1') ctx.fillRect(x, opts.margin, opts.width, opts.height);
        x += opts.width;
      }
      if(opts.displayValue){
        ctx.font = `bold ${opts.fontSize}px monospace`;
        ctx.textAlign = 'center';
        ctx.fillText(text, w/2, opts.margin + opts.height + opts.fontSize + 2);
      }
    }
  }
  global.JsBarcode = JsBarcode;
})(window);
